INSERT INTO requirement (id, workspace_id, name, description, status, created_at, updated_at) VALUES
  ('YyR01', 'SYy01', '资金通', '多柜台次席账户间资金划转与出入金的统一管理，确保资金操作全流程100%可追溯、可冲正。', 'active', '2026-06-01 09:00:00', '2026-06-01 09:00:00'),
  ('YyR02', 'SYy01', '流程引擎', '提供流程全生命周期管理能力——包括 BPMN 可视化流程设计、多模式审批（会签/或签/加批/转办/委托等）、SpEL 条件引擎动态路由等', 'active', '2026-06-01 09:00:00', '2026-06-01 09:00:00'),
  ('YyR03', 'SYy01', '风控与合规', '通过自主研发，打造一套统一、智能、全覆盖的风险管理平台', 'active', '2026-06-01 09:00:00', '2026-06-01 09:00:00'),
  ('YyR04', 'SYy01', '报表服务', '报表服务旨在通过低代码方式快速构建可视化报表，通过API或数据库方式实现报表的搭建，预览，发送等', 'done', '2026-06-01 09:00:00', '2026-06-01 09:00:00'),
  ('YyR05', 'SYy01', 'API开放平台', 'API网关管理系统，用于管理第三方系统对企业内部API的访问——通过 appKey/appSecret 签名认证、细粒度权限控制、接口级限流和IP白名单等机制，为内部业务服务提供统一的API安全入口', 'done', '2026-06-01 09:00:00', '2026-06-01 09:00:00'),
  ('YyR06', 'SYy01', '消息中心', '支持多渠道（短信、企微等）消息发送的独立通知平台，提供消息模板自定义、应用接入及接收人动态配置能力，供各业务系统统一集成调用。', 'done', '2026-06-01 09:00:00', '2026-06-01 09:00:00'),
  ('YyR07', 'SYy01', '机构服务平台', '客户一站式服务平台', 'active', '2026-06-01 09:00:00', '2026-06-01 09:00:00'),
  ('YyR08', 'SYy01', 'AI知识库', '利用AI实现知识库管理，Agent开发等', 'active', '2026-06-01 09:00:00', '2026-06-01 09:00:00'),
  ('YyR09', 'SYy01', '小程序平台化', '配合寰球，梳理现有小程序，将其平台化，解决以下痛点：\n1、数据来源不一致，过渡依赖手工收集;\n2、配置参数散落在各工作站上，且无备份；\n3、无工作日志；\n4、结果数据未落库；\n5、程序运行自动化程度低；\n6、下班时间后，缺少运维值守。', 'active', '2026-06-01 09:00:00', '2026-06-01 09:00:00');
INSERT INTO project_version (id, workspace_id, req_id, name, description, status, target_date, released_at, created_at) VALUES
  ('YyV01', 'SYy01', 'YyR02', 'V0.8', '软件台账写入,程序化报备录入成功消息发送,软件台账写入,外接台账新增时间筛选', 'released', '2026-06-15', '2026-06-15 10:00:00', '2026-06-15 10:00:00'),
  ('YyV02', 'SYy01', 'YyR02', 'V0.81', '外接软件台账支持编辑和查询', 'released', '2026-06-16', '2026-06-16 10:00:00', '2026-06-16 10:00:00'),
  ('YyV03', 'SYy01', 'YyR02', 'V0.82', '常用语设置,外接推送OA待办标题名称调整', 'released', '2026-06-24', '2026-06-24 10:00:00', '2026-06-24 10:00:00'),
  ('YyV04', 'SYy01', 'YyR02', 'V0.9', '外接流程下拉选项调整,外接测试报告自动化生成,子账户台账调整,是否签署承诺函下拉框修改,审批结束后关闭待办,系统是否有界面下拉框修改,软件台账编辑功能，上传附件限制修改至100M,软件台账新增是否有界面字段,尽职调查字段下新增注释,外接子账户台账显示创建时间,外接流程新增模式下根据appid计算子账户系统核实字段', 'released', '2026-06-29', '2026-06-29 10:00:00', '2026-06-29 10:00:00'),
  ('YyV05', 'SYy01', 'YyR02', '发版-20260708', '软件台账新增是否有界面字段,外接流程解绑 appId修改为下拉选择,催办,流程终止发送消息给发起人-企微,外接合规报告生成渲染文本调整,外接流程管理菜单新增部分筛选字段,子账户台账模块重构', 'released', '2026-07-08', '2026-07-08 10:00:00', '2026-07-08 10:00:00'),
  ('YyV06', 'SYy01', 'YyR02', '发版-20260715', '子账户黑名单,外接生产授权码出来后，推送企微消息给发起人,外接流程界面查询优化,外接台账新增字段测试反馈表(Word/Excel),提供根据客户号查询是否存在有在途和生效的外接信息,分户管理资产交易编码对应名称 获取,客户实时数据同步,外接标题优化,销户流程对接,直链接模式和中继模式对于技术架构绑定关系,客户是自然人，且选择的外部接入标识为子账户，则不允许发起外接流程', 'released', '2026-07-15', '2026-07-15 10:00:00', '2026-07-15 10:00:00'),
  ('YyV07', 'SYy01', 'YyR02', '发版-20260723', '外接台账新增字段测试反馈表(Word/Excel),推送移动端消息链接URL为PC端链接，打开页面不正确,退回修改界面的上传的附件，在审批记录中不展示,分户管理资产交易编码对应名称 获取,客户实时数据同步,外接合规报告优化', 'released', '2026-07-23', '2026-07-23 10:00:00', '2026-07-23 10:00:00'),
  ('YyV08', 'SYy01', 'YyR02', '发版-20260729', '流程通用优化,程序化待办列宽自定义,暂存列表实现,主机托管台账单独签出,子账户台账自动写入', 'released', '2026-07-29', '2026-07-29 10:00:00', '2026-07-29 10:00:00'),
  ('YyV09', 'SYy01', 'YyR02', '发版-20260819', '新增待办页面供业务中台iframe嵌入查看,交还报表,手机端审批页面未正常关闭,子账户签报合并调整，避免多次审批,平台切换对接外接流程获取APPID,流程引擎退回BUG,外接-流程复制-已有模式下-部分字段改为台账覆盖,外接摘要固定优化', 'released', '2026-08-19', '2026-08-19 10:00:00', '2026-08-19 10:00:00'),
  ('YyV10', 'SYy01', 'YyR02', 'V1.2.0', NULL, 'planned', NULL, NULL, '2026-06-01 09:00:00');
INSERT INTO demand (id, workspace_id, req_id, title, description, source, item_kind, priority, status, review_note, created_by, created_at, updated_at) VALUES
  ('YyQ001', 'SYy01', 'YyR02', '主机托管历史数据迁移', '将OA的主机托管台账迁移到本系统', NULL, '新功能', 'P2', 'plan', NULL, NULL, '2026-06-09 09:00:00', '2026-06-09 09:00:00'),
  ('YyQ002', 'SYy01', 'YyR02', '主机托管流程', '从OA流程迁移主机托管流程，实现主机托管流程的流转等', NULL, '新功能', 'P2', 'plan', NULL, NULL, '2026-06-09 09:00:00', '2026-06-09 09:00:00'),
  ('YyQ003', 'SYy01', 'YyR02', '主机托管表单', '从OA流程迁移主机托管流程，实现主机托管表单逻辑的联动等', NULL, '新功能', 'P2', 'plan', NULL, NULL, '2026-06-09 09:00:00', '2026-06-09 09:00:00'),
  ('YyQ004', 'SYy01', 'YyR02', '外接台账写入', '1、在中台底表（台账表：t_biz_software_ledger）中加这个字段，然后文件落地表。为了后期检查。\n2、如果选已有，之前没有上传过子账户说明文件的，在审批意见——发起人中需要上传子账户功能证明材料（必填）\n3、流程到一个组（组中人审批这个说明文件，或签，包含界面和非界面审批人）\n4、已有授权这个流程走完，回写到台账表中，子账户功能证明材料和子账户材料确认', NULL, '新功能', 'P2', 'plan', NULL, NULL, '2026-06-08 09:00:00', '2026-06-08 09:00:00'),
  ('YyQ005', 'SYy01', 'YyR02', '企微消息推送', '外接流程，新增授权码当中台程序化报备信息录入（即程序化信息写入监听器）后，触发企微消息给发起人', NULL, '新功能', 'P2', 'plan', NULL, NULL, '2026-06-08 09:00:00', '2026-06-08 09:00:00'),
  ('YyQ006', 'SYy01', 'YyR02', '外接台账查看', '外接台账新增筛选便于业务人员使用', NULL, '新功能', 'P2', 'plan', NULL, NULL, '2026-06-08 09:00:00', '2026-06-08 09:00:00'),
  ('YyQ007', 'SYy01', 'YyR02', '对于审批人发起附言是否有常用语功能', '对于审批人发起附言是否有常用语功能', NULL, '新功能', 'P2', 'plan', NULL, NULL, '2026-06-10 09:00:00', '2026-06-10 09:00:00'),
  ('YyQ008', 'SYy01', 'YyR02', '流程功能节点处理时长展示', '对于流程中处理卡点，做个统计。知道流程时间长是卡在哪里，怎么做优化', '周顺', '体验优化', 'P2', 'review', NULL, NULL, '2026-06-10 09:00:00', '2026-06-10 09:00:00'),
  ('YyQ009', 'SYy01', 'YyR02', '消户时提示他需要把外接解除绑定', '客户号消户，需要对于这个客户号走过的外接发起解除绑定', '周顺', '新功能', 'P2', 'plan', NULL, NULL, '2026-06-12 09:00:00', '2026-06-12 09:00:00'),
  ('YyQ010', 'SYy01', 'YyR02', '外接和程序化报备做到穿透', '在外接中走到程序化报备用流程，做个穿透，可以在个流程中知道报备走到哪里了', '周顺', '新功能', 'P2', 'plan', NULL, NULL, '2026-06-12 09:00:00', '2026-06-12 09:00:00'),
  ('YyQ011', 'SYy01', 'YyR01', '资金通资金信息查询', '资金通资金信息查询', NULL, '新功能', 'P2', 'plan', NULL, NULL, '2026-06-15 09:00:00', '2026-06-15 09:00:00'),
  ('YyQ012', 'SYy01', 'YyR02', '业务中台的主界面显示外接程序化代办', '在业务中台的主界面中显示后期流程引擎的代办', '周顺', '新功能', 'P2', 'plan', NULL, NULL, '2026-06-16 09:00:00', '2026-06-16 09:00:00'),
  ('YyQ013', 'SYy01', 'YyR02', '流程中被回退的在代办中特殊显示', '流程中被回退的在代办中特殊显示，于正常代办流程有所区别，可以高亮或标识来区别', '周顺', '新功能', 'P2', 'plan', NULL, NULL, '2026-06-16 09:00:00', '2026-06-16 09:00:00'),
  ('YyQ014', 'SYy01', 'YyR02', '业务办理销户时提示未解除流程', '业务办理销户时提示未解除流程，比如未外接解绑或托管流程未注销等', '周顺', '新功能', 'P2', 'plan', NULL, NULL, '2026-06-16 09:00:00', '2026-06-16 09:00:00'),
  ('YyQ015', 'SYy01', 'YyR02', '外接测试报告自动化生成功能', '概要：通过外接流程的字段和外接审核人填写的字段，自动化生成word版外接测试报告。\n1）报告的表头，程序名，版本号，appid，连接模式，柜台名称，测试审核人，预审人，当天日期均可以从流程中获取。\n2）测试时间，测试账号，12个测试结果勾选，默认值参考报告模板。\n3）柜台明细信息，与柜台名称绑定。\n4）测试结论勾选，根据流程的“是否允许外接不允许程序化”的值，如果是允许外接允许程序化，则勾选通过；如果允许外接不允许程序化，则勾选不建议；如果不允许外接不允许程序化，则勾选不通过。\n4）支持在测试审核节点多次生成，保留最新一次结果。', '林潇', '新功能', 'P2', 'plan', NULL, NULL, '2026-06-16 09:00:00', '2026-06-16 09:00:00'),
  ('YyQ016', 'SYy01', 'YyR02', '业务平台基础功能', NULL, NULL, '新功能', 'P2', 'plan', NULL, NULL, '2026-06-17 09:00:00', '2026-06-17 09:00:00'),
  ('YyQ017', 'SYy01', 'YyR02', '标题依据流程处理时效不同显示不同', '标题依据流程处理时效不同显示不同，方便值班员及时处理，显示如下：\n已有授权+黄智峰-88867899+CTP+信息系统外部接入审批：\n新增授权+黄智峰-88867899+CTP+信息系统外部接入审批', '邱德华', '新功能', 'P2', 'plan', NULL, NULL, '2026-06-17 09:00:00', '2026-06-17 09:00:00'),
  ('YyQ018', 'SYy01', 'YyR01', '次席资金监控', '落地资金通系统，实现全次席柜台全时段资金监控、自动预警通知，补齐原有系\n统能力短板', NULL, '新功能', 'P2', 'plan', NULL, NULL, '2026-06-22 09:00:00', '2026-06-22 09:00:00'),
  ('YyQ019', 'SYy01', 'YyR02', '与合规确认外接流程需要优化', '1、情况说明变成软件基本情况说明----孔\n2、子账户数量---孔\n3、子账户选是，要上传附件---孔\n4、加黑名单，静止接入----孔\n5、已有授权中，子账户材料确认是测试人员-----孔\n6、允许外接，不入报备，也需要落台帐-----孔\n7、是否允许程序报报备，落地表-----孔\n8、软件基本情况说明中协议有/无增改---孔（无人审批，暂时隐藏）\n\n1、是否有分仓管理系统是多账户还是子账户的意思-----朱斌验收查看（不改动）\n2、对于测试人员中的子账户材料确认改成为子账户功能证明材料判断结果，下拉选项：有子账户功能/未见子账户功能界面\n	  对于是否允许外接不允许程序化改为是否可以程序化报备用，下拉选项：不报备/可以报备', '周顺', '体验优化', 'P2', 'plan', NULL, NULL, '2026-06-22 09:00:00', '2026-06-22 09:00:00'),
  ('YyQ020', 'SYy01', 'YyR02', '子账户台帐', '同一个APPID对于子账户台帐上的软件名和软件版本与外接软件信息台帐内容保持一致', '周顺', '新功能', 'P2', 'plan', NULL, NULL, '2026-06-22 09:00:00', '2026-06-22 09:00:00'),
  ('YyQ021', 'SYy01', 'YyR02', '在流程中支持配置超时自动审批通过', '对于领导存在开会等情况，无法及时审批，因此支持配置超时自动审批通过', '王越峰', '新功能', 'P2', 'plan', NULL, NULL, '2026-06-23 09:00:00', '2026-06-23 09:00:00'),
  ('YyQ022', 'SYy01', 'YyR02', '外部系统解绑审批', '外部系统解绑审批需增加运维部门全量客户查询和批量导入功能，方便我们批量导入已经销户用户', '邱德华', '新功能', 'P2', 'plan', NULL, NULL, '2026-06-23 09:00:00', '2026-06-23 09:00:00'),
