  ('YyQ049', 'SYy01', 'YyR02', '外接流程内容显示优化', '流程点开以后，标题显示需优化为：已有授权+ 申请人+账户+appid+系统类型，如下图', '邱德华', '体验优化', 'P2', 'plan', NULL, NULL, '2026-06-30 09:00:00', '2026-06-30 09:00:00'),
